        let bg = BG[ai]; let fg = FG[ai]; let gz = GZ[ai]; let cp = CP[ai]; let sg = SG[ai];
        let pier = 0.35 + 0.25 * r; var lo = vec2f(pier, 0.12); var hi = vec2f(sw - pier, openHi);
        var open = fBx(p, lo, hi, aw);
        if (gz > 4.5 && gz < 5.5) { let rad = min((hi.x - lo.x) * 0.5, hi.y - 1.2); let ay = hi.y - rad; let dxa = max(abs(fx - mid) - ((hi.x - lo.x) * 0.5 - rad), 0.0); open *= 1.0 - fSS(rad - px, rad + px, length(vec2f(dxa, max(fy - ay, 0.0)))); }
        // surround in the shop's own colour
        let sur = fBx(p, lo - vec2f(0.16, 0.2), hi + vec2f(0.16, 0.16), aw); col = mix(col, mix(bg, podC, 0.25) * 0.9, sur * step(0.5, gz)); 
