          let tt = vec2f(fSf(slope.x > 0.0, hi.x - p.x, p.x - lo.x), fSf(slope.y > 0.0, hi.y - p.y, p.y - lo.y)) / (abs(slope) + 1e-4); let t = min(min(tt.x, tt.y), dR);
          let g = p + slope * t; let rr = fRoom(g, slope, vec2f(sw, shopTop - 0.6), 5.0 + 4.0 * r2, vec2f(id, sd * 17.0), 1.0); let tintI = mix(vec3f(1.0, 0.94, 0.84), mix(fg, vec3f(1.0), 0.6), 0.5);
          var oc = mix(rr.c * (0.2 + 0.5 * rr.fall) * 0.6, vec3f(0.50, 0.56, 0.62), 0.3); var oem = (rr.c * (0.3 + 0.6 * rr.fall) + rr.glow * 1.2) * tintI * lightsOn; var orough = 0.06; var ometal = 0.45;
          var fr = 1.0 - fBx(g, lo + 0.05, hi - 0.05, aw); fr = max(fr, max(fLn(g.x, mid - 1.0, 0.025, fw.x), fLn(g.x, mid + 1.0, 0.025, fw.x)) * step(g.y, 2.5)); fr = max(fr, fLn(g.y, 2.5, 0.025, fw.y) * doorM); fr = max(fr, fLn(g.x, mid, 0.012, fw.x) * doorM);
          var frC = vec3f(0.10, 0.11, 0.12);
          if (gz > 0.5 && gz < 1.5) { let q = (g - lo) / vec2f(0.8, 0.8); fr = max(fr, (1.0 - min(fLn(fract(q.x), 0.5, 0.47, fw.x / 0.8), fLn(fract(q.y), 0.5, 0.47, fw.y / 0.8))) * (1.0 - doorM)); }
          else if (gz > 1.5 && gz < 2.5) { frC = vec3f(0.22, 0.12, 0.06); let up = step(hi.y - 0.95, g.y); let dq = vec2f(g.x + g.y, g.x - g.y) / 0.34; let lat = (1.0 - fLn(fract(dq.x), 0.5, 0.42, fw.x / 0.3) * fLn(fract(dq.y), 0.5, 0.42, fw.x / 0.3)) * up * det;
            fr = max(fr, max(lat, (1.0 - fLn(fract((g.x - lo.x) / 0.7), 0.5, 0.46, fw.x / 0.7)) * (1.0 - doorM) * (1.0 - up))); fr = max(fr, fLn(g.y, hi.y - 0.95, 0.04, fw.y)); }
          else if (gz > 2.5 && gz < 3.5) { let ctr = step(g.y, 1.05) * (1.0 - doorM); let top = fLn(g.y, 1.05, 0.05, fw.y) * (1.0 - doorM);                 // counter: tiled front, timber top, open above
            let tl = fract(g / vec2f(0.2, 0.2)); let tj = min(fLn(tl.x, 0.5, 0.45, fw.x / 0.2), fLn(tl.y, 0.5, 0.45, fw.y / 0.2));
            oc = mix(oc, mix(bg, vec3f(0.9), 0.55 * step(0.5, fH21(floor(g / 0.2)))) * mix(0.7, 1.0, mix(1.0, tj, det)), ctr); oem *= 1.0 - ctr; orough = mix(orough, 0.3, ctr); ometal *= 1.0 - ctr; oc = mix(oc, vec3f(0.40, 0.26, 0.14), top); oem *= 1.0 - top;
            let lant = fSS(0.2, 0.16, length(vec2f(fMod(g.x - lo.x, 1.5) - 0.75, (g.y - (hi.y - 0.42)) * 0.8))) * (1.0 - doorM); oc = mix(oc, fg * 0.8, lant); oem = mix(oem, fg * (0.5 + night) * 1.2, lant); }
          else if (gz > 3.5 && gz < 4.5) { let q = (g - vec2f(lo.x, lo.y)) / vec2f(0.52, 0.46); let qi = floor(q); let qf = fract(q); let cell = fBx(qf, vec2f(0.05, 0.06), vec2f(0.95, 0.94), aw / vec2f(0.52, 0.46)) * (1.0 - doorM);   // parcel lockers
            let hc = fH21(qi + sd * 9.0); let lc = mix(mix(bg, vec3f(0.85), 0.5), fg, step(0.86, hc)); oc = mix(oc, mix(vec3f(0.08), lc * (0.9 + 0.1 * hc), mix(0.9, cell, det)), 1.0 - doorM); oem *= doorM; orough = mix(0.4, orough, doorM); ometal = mix(0.5, ometal, doorM);
            let led = fSS(0.07, 0.04, length(qf - vec2f(0.84, 0.5))) * det * (1.0 - doorM); oem += mix(vec3f(0.1, 1.0, 0.4), vec3f(1.0, 0.6, 0.1), step(0.7, hc)) * led * (0.4 + night); }
          else if (gz > 5.5 && gz < 6.5) { let band = step(0.7, g.y) * step(g.y, 1.9) * (1.0 - doorM); oc = mix(oc, mix(vec3f(0.80, 0.84, 0.84), bg, 0.25), band * 0.85); oem = mix(oem, oem * 0.6 + tintI * 0.1 * lightsOn, band); orough = mix(orough, 0.5, band);
            let mot = step(0.5, fH21(floor(g / vec2f(0.4, 0.4)) + sd)) * fBx(fract(g / vec2f(0.4, 0.4)), vec2f(0.3), vec2f(0.7), aw / 0.4) * band * det; oc = mix(oc, fg * 0.7, mot); }
          else if (gz > 6.5) { oc *= 0.45; let inset = fBx(g, lo + 0.22, hi - 0.22, aw) * (1.0 - fBx(g, lo + 0.29, hi - 0.29, aw)); let ph = 0.6 + 0.4 * sin(uTime * 2.1 + r * 6.0); oc = mix(oc, fg, inset); oem = mix(oem * 0.7 + fg * 0.08 * lightsOn, fg * (0.6 + 1.6 * night) * ph, inset);
            let tri = fSS(0.03, 0.0, abs(fract((g.x + g.y * 0.6) / 1.3 - uTime * 0.05) - 0.5) - 0.02) * step(2.6, g.y); oem += mix(fg, vec3f(0.2, 0.6, 1.0), 0.5) * tri * (0.2 + night) * 0.6; }
          if (t < dR - 1e-4) { let side = step(tt.x, tt.y); oc = mix(bg, podC, 0.4) * 0.6; oem = vec3f(0.0); orough = 0.5; ometal = 0.0; gTn = normalize(fS3(side > 0.5, vec3f(fSf(slope.x > 0.0, -1.0, 1.0), 0.0, 0.12), vec3f(0.0, fSf(slope.y > 0.0, -1.0, 1.0), 0.12))); flatN = 1.0; if (side < 0.5 && slope.y > 0.0) { oc *= 0.5; } }
          else { fr *= mix(0.4, 1.0, det2); oc = mix(oc, frC, fr); oem *= 1.0 - fr; orough = mix(orough, 0.35, fr); ometal = mix(ometal, 0.7, fr); }
