        let rib = fBx(p, vec2f(sw * 0.3, 0.5), vec2f(sw * 0.7, shopTop - 1.5), aw) * step(0.4, r); let rb = sin(fx / 0.12 * 6.2831); col *= 1.0 - 0.18 * rib * (0.5 + 0.5 * rb) * det; bump.x += rb * 0.4 * rib * det;
        let slot = fBx(p, vec2f(0.5, shopTop - 1.02), vec2f(sw - 0.5, shopTop - 0.94), aw); col = mix(col, vec3f(0.9, 0.85, 0.7), slot); emis = warm * slot * (0.15 + 1.3 * night);
