    let photoK = photoOn * step(shopTop + 0.2, vF.y) * (1.0 - step(0.5, indus)) * (1.0 - uNight * 0.62) * fSf(glassy > 0.5, 0.52, 0.82) * (0.65 + 0.35 * heritage);
