    if (abs(info.w) > 0.5 && uShow.y > 0.01 && vF.y > shopTop + 0.4 && fromTop > 0.3) { let L = fShow(vec2f(abs(info.w), vF.y), uShow.x, vec2f(fw.x, fw.y), sign(info.w)); let m = L.a * uShow.y;
      col = mix(col, col * 0.3, m * 0.8); emis = mix(emis, L.rgb * 1.5, m); rough = mix(rough, 0.35, m * 0.6); metal = mix(metal, 0.0, m); pvMask *= 1.0 - m; }
